85	// 0: no gap in this block.
86	// 1: has max gap in level 1 in this block.
87	// ...
88	type GapLevel = number;
89	// See `TooltipMarkupLayoutIntent['innerGapLevel']`.
90	// (value from UI design)
91	const HTML_GAPS: Record<GapLevel, number> = [0, 10, 20, 30];
92	const RICH_TEXT_GAPS: Record<GapLevel, string> = ['', '\n', '\n\n', '\n\n\n'];
93	
94	/**
95	 * This is an abstract layer to insulate the upper usage of tooltip content
96	 * from the different backends according to different `renderMode` ('html' or 'richText').
97	 * With the help of the abstract layer, it does not need to consider how to create and
98	 * assemble html or richText snippets when making tooltip content.
99	 *
100	 * @usage
101	 *
102	 * ```ts
103	 * class XxxSeriesModel {
104	 *     formatTooltip(
105	 *         dataIndex: number,
106	 *         multipleSeries: boolean,
107	 *         dataType: string
108	 *     ) {
109	 *         ...
110	 *         return createTooltipMarkup('section', {
111	 *             header: header,
112	 *             blocks: [
113	 *                 createTooltipMarkup('nameValue', {
114	 *                     name: name,
115	 *                     value: value,
116	 *                     noValue: value == null
117	 *                 })
118	 *             ]
119	 *         });
120	 *     }
121	 * }
122	 * ```
123	 */
124	export type TooltipMarkupBlockFragment =
125	    TooltipMarkupSection
126	    | TooltipMarkupNameValueBlock;
127	
128	interface TooltipMarkupBlock {
129	    // Use to make comparison when `sortBlocks: true`.
130	    sortParam?: unknown;
131	}
132	
133	export interface TooltipMarkupSection extends TooltipMarkupBlock {
134	    type: 'section';
135	    header?: unknown;
136	    // If `noHeader` is `true`, do not display header.
137	    // Otherwise, always display it even if it is
138	    // null/undefined/NaN/''... (displayed as '-').
139	    noHeader?: boolean;
140	    blocks?: TooltipMarkupBlockFragment[];
141	    // Enable to sort blocks when making final html or richText.
142	    sortBlocks?: boolean;
143	
144	    valueFormatter?: CommonTooltipOption<unknown>['valueFormatter']
145	}
146	
147	export interface TooltipMarkupNameValueBlock extends TooltipMarkupBlock {
148	    type: 'nameValue';
149	    // If `!markerType`, tooltip marker is not used.
150	    markerType?: TooltipMarkerType;
151	    markerColor?: ColorString;
152	    name?: string;
153	    // Also support value is `[121, 555, 94.2]`.
154	    value?: unknown | unknown[];
155	    // If not specified, treat value as normal string or numeric.
156	    // If needs to display formatted time, set as 'time'.
157	    // If needs to display original string with numeric guessing, set as 'ordinal'.
158	    // If both `value` and `valueType` are array, each valueType[i] cooresponds to value[i].
159	    valueType?: DimensionType | DimensionType[];
160	    // If `noName` or `noValue` is `true`, do not display name or value.
161	    // Otherwise, always display them even if they are
162	    // null/undefined/NaN/''... (displayed as '-').
163	    noName?: boolean;
164	    noValue?: boolean;
165	    dataIndex?: number;
166	
167	    valueFormatter?: CommonTooltipOption<unknown>['valueFormatter']
168	}
169	
170	/**
171	 * Create tooltip markup by this function, we can get TS type check.
172	 */
173	// eslint-disable-next-line max-len
174	export function createTooltipMarkup(type: 'section', option: Omit<TooltipMarkupSection, 'type'>): TooltipMarkupSection;
175	// eslint-disable-next-line max-len
176	export function createTooltipMarkup(type: 'nameValue', option: Omit<TooltipMarkupNameValueBlock, 'type'>): TooltipMarkupNameValueBlock;
177	// eslint-disable-next-line max-len
178	export function createTooltipMarkup(type: TooltipMarkupBlockFragment['type'], option: Omit<TooltipMarkupBlockFragment, 'type'>): TooltipMarkupBlockFragment {
179	    (option as TooltipMarkupBlockFragment).type = type;
180	    return option as TooltipMarkupBlockFragment;
181	}
