183	
184	// Can be null/undefined, which means generate nothing markup text.
185	type MarkupText = string;
186	interface TooltipMarkupFragmentBuilder {
187	    (
188	        ctx: TooltipMarkupBuildContext,
189	        fragment: TooltipMarkupBlockFragment,
190	        topMarginForOuterGap: number,
191	        toolTipTextStyle: TooltipOption['textStyle']
192	    ): MarkupText;
193	}
194	
195	function isSectionFragment(frag: TooltipMarkupBlockFragment): frag is TooltipMarkupSection {
196	    return frag.type === 'section';
197	}
198	
199	function getBuilder(frag: TooltipMarkupBlockFragment): TooltipMarkupFragmentBuilder {
200	    return isSectionFragment(frag) ? buildSection : buildNameValue;
201	}
202	
203	function getBlockGapLevel(frag: TooltipMarkupBlockFragment) {
204	    if (isSectionFragment(frag)) {
205	        let gapLevel = 0;
206	        const subBlockLen = frag.blocks.length;
207	        const hasInnerGap = subBlockLen > 1 || (subBlockLen > 0 && !frag.noHeader);
208	        each(frag.blocks, function (subBlock) {
209	            const subGapLevel = getBlockGapLevel(subBlock);
210	            // If the some of the sub-blocks have some gaps (like 10px) inside, this block
211	            // should use a larger gap (like 20px) to distinguish those sub-blocks.
212	            if (subGapLevel >= gapLevel) {
213	                gapLevel = subGapLevel + (
214	                    +(
215	                        hasInnerGap && (
216	                            // 0 always can not be readable gap level.
217	                            !subGapLevel
218	                            // If no header, always keep the sub gap level. Otherwise
219	                            // look weird in case `multipleSeries`.
220	                            || (isSectionFragment(subBlock) && !subBlock.noHeader)
221	                        )
222	                    )
223	                );
224	            }
225	        });
226	        return gapLevel;
227	    }
228	    return 0;
229	}
230	
231	function buildSection(
232	    ctx: TooltipMarkupBuildContext,
233	    fragment: TooltipMarkupSection,
234	    topMarginForOuterGap: number,
235	    toolTipTextStyle: TooltipOption['textStyle']
236	) {
237	    const noHeader = fragment.noHeader;
238	
239	    const gaps = getGap(getBlockGapLevel(fragment));
240	
241	    const subMarkupTextList: string[] = [];
242	    let subBlocks = fragment.blocks || [];
243	    assert(!subBlocks || isArray(subBlocks));
244	    subBlocks = subBlocks || [];
245	
246	    const orderMode = ctx.orderMode;
247	    if (fragment.sortBlocks && orderMode) {
248	        subBlocks = subBlocks.slice();
249	        const orderMap = { valueAsc: 'asc', valueDesc: 'desc' } as const;
250	        if (hasOwn(orderMap, orderMode)) {
251	            const comparator = new SortOrderComparator(orderMap[orderMode as 'valueAsc' | 'valueDesc'], null);
252	            subBlocks.sort((a, b) => comparator.evaluate(a.sortParam, b.sortParam));
253	        }
254	        // FIXME 'seriesDesc' necessary?
255	        else if (orderMode === 'seriesDesc') {
256	            subBlocks.reverse();
257	        }
258	    }
259	
260	    each(subBlocks, function (subBlock, idx) {
261	        const valueFormatter = fragment.valueFormatter;
262	        const subMarkupText = getBuilder(subBlock)(
263	            // Inherit valueFormatter
264	            valueFormatter ? extend(extend({}, ctx), { valueFormatter }) : ctx,
265	            subBlock,
266	            idx > 0 ? gaps.html : 0,
267	            toolTipTextStyle
268	        );
269	        subMarkupText != null && subMarkupTextList.push(subMarkupText);
270	    });
271	
272	    const subMarkupText = ctx.renderMode === 'richText'
273	        ? subMarkupTextList.join(gaps.richText)
274	        : wrapBlockHTML(
275	            subMarkupTextList.join(''),
276	            noHeader ? topMarginForOuterGap : gaps.html
277	        );
278	
279	    if (noHeader) {
280	        return subMarkupText;
281	    }
282	
283	    const displayableHeader = makeValueReadable(fragment.header, 'ordinal', ctx.useUTC);
284	    const {nameStyle} = getTooltipTextStyle(toolTipTextStyle, ctx.renderMode);
285	    if (ctx.renderMode === 'richText') {
286	        return wrapInlineNameRichText(ctx, displayableHeader, nameStyle as RichTextStyle) + gaps.richText
287	            + subMarkupText;
288	    }
289	    else {
290	        return wrapBlockHTML(
291	            `<div style="${nameStyle};${TOOLTIP_LINE_HEIGHT_CSS};">`
292	                + encodeHTML(displayableHeader)
293	                + '</div>'
294	                + subMarkupText,
295	            topMarginForOuterGap
296	        );
297	    }
298	}
299	
300	function buildNameValue(
301	    ctx: TooltipMarkupBuildContext,
302	    fragment: TooltipMarkupNameValueBlock,
303	    topMarginForOuterGap: number,
304	    toolTipTextStyle: TooltipOption['textStyle']
305	) {
306	    const renderMode = ctx.renderMode;
307	    const noName = fragment.noName;
308	    const noValue = fragment.noValue;
309	    const noMarker = !fragment.markerType;
310	    const name = fragment.name;
311	    const useUTC = ctx.useUTC;
312	    const valueFormatter = fragment.valueFormatter || ctx.valueFormatter || ((value) => {
313	        value = isArray(value) ? value : [value];
314	        return map(value as unknown[], (val, idx) => makeValueReadable(
315	            val, isArray(valueTypeOption) ? valueTypeOption[idx] : valueTypeOption, useUTC
316	        ));
317	    });
318	
319	    if (noName && noValue) {
320	        return;
321	    }
322	
323	    const markerStr = noMarker
324	        ? ''
325	        : ctx.markupStyleCreator.makeTooltipMarker(
326	            fragment.markerType,
327	            fragment.markerColor || '#333',
328	            renderMode
329	        );
330	    const readableName = noName
331	        ? ''
332	        : makeValueReadable(name, 'ordinal', useUTC);
333	    const valueTypeOption = fragment.valueType;
334	    const readableValueList = noValue
335	        ? []
336	        : valueFormatter(fragment.value as OptionDataValue, fragment.dataIndex);
337	    const valueAlignRight = !noMarker || !noName;
338	    // It little weird if only value next to marker but far from marker.
339	    const valueCloseToMarker = !noMarker && noName;
340	
341	    const {nameStyle, valueStyle} = getTooltipTextStyle(toolTipTextStyle, renderMode);
342	
343	    return renderMode === 'richText'
344	        ? (
345	            (noMarker ? '' : markerStr)
346	            + (noName ? '' : wrapInlineNameRichText(ctx, readableName, nameStyle as RichTextStyle))
347	            // Value has commas inside, so use ' ' as delimiter for multiple values.
348	            + (noValue ? '' : wrapInlineValueRichText(
349	                ctx, readableValueList, valueAlignRight, valueCloseToMarker, valueStyle as RichTextStyle
350	            ))
351	        )
352	        : wrapBlockHTML(
353	            (noMarker ? '' : markerStr)
354	            + (noName ? '' : wrapInlineNameHTML(readableName, !noMarker, nameStyle as string))
355	            + (noValue ? '' : wrapInlineValueHTML(
356	                readableValueList, valueAlignRight, valueCloseToMarker, valueStyle as string
357	            )),
358	            topMarginForOuterGap
359	        );
360	}
361	
362	interface TooltipMarkupBuildContext {
363	    useUTC: boolean;
364	    renderMode: TooltipRenderMode;
365	    orderMode: TooltipOrderMode;
366	    markupStyleCreator: TooltipMarkupStyleCreator;
367	
368	    valueFormatter: CommonTooltipOption<unknown>['valueFormatter']
369	}
370	
371	/**
372	 * @return markupText. null/undefined means no content.
373	 */
374	export function buildTooltipMarkup(
375	    fragment: TooltipMarkupBlockFragment,
376	    markupStyleCreator: TooltipMarkupStyleCreator,
377	    renderMode: TooltipRenderMode,
378	    orderMode: TooltipOrderMode,
379	    useUTC: boolean,
380	    toolTipTextStyle: TooltipOption['textStyle']
381	): MarkupText {
382	    if (!fragment) {
383	        return;
384	    }
385	
386	    const builder = getBuilder(fragment);
387	    const ctx: TooltipMarkupBuildContext = {
388	        useUTC: useUTC,
389	        renderMode: renderMode,
390	        orderMode: orderMode,
391	        markupStyleCreator: markupStyleCreator,
392	        valueFormatter: fragment.valueFormatter
393	    };
394	    return builder(ctx, fragment, 0, toolTipTextStyle);
395	}
396	
397	
398	function getGap(gapLevel: number): {
399	    html: number;
400	    richText: string
401	} {
402	    return {
403	        html: HTML_GAPS[gapLevel],
404	        richText: RICH_TEXT_GAPS[gapLevel]
405	    };
406	}
407	
408	function wrapBlockHTML(
409	    encodedContent: string,
410	    topGap: number
411	): string {
412	    const clearfix = '<div style="clear:both"></div>';
413	    const marginCSS = `margin: ${topGap}px 0 0`;
414	    return `<div style="${marginCSS};${TOOLTIP_LINE_HEIGHT_CSS};">`
415	        + encodedContent + clearfix
416	        + '</div>';
417	}
418	
419	function wrapInlineNameHTML(
420	    name: string,
421	    leftHasMarker: boolean,
422	    style: string
423	): string {
424	    const marginCss = leftHasMarker ? 'margin-left:2px' : '';
425	    return `<span style="${style};${marginCss}">`
426	        + encodeHTML(name)
427	        + '</span>';
428	}
429	
430	function wrapInlineValueHTML(
431	    valueList: string | string[],
432	    alignRight: boolean,
433	    valueCloseToMarker: boolean,
434	    style: string
435	): string {
436	    // Do not too close to marker, considering there are multiple values separated by spaces.
437	    const paddingStr = valueCloseToMarker ? '10px' : '20px';
438	    const alignCSS = alignRight ? `float:right;margin-left:${paddingStr}` : '';
439	    valueList = isArray(valueList) ? valueList : [valueList];
440	    return (
441	        `<span style="${alignCSS};${style}">`
442	        // Value has commas inside, so use '  ' as delimiter for multiple values.
443	        + map(valueList, value => encodeHTML(value)).join('&nbsp;&nbsp;')
444	        + '</span>'
445	    );
446	}
447	
448	function wrapInlineNameRichText(ctx: TooltipMarkupBuildContext, name: string, style: RichTextStyle): string {
449	    return ctx.markupStyleCreator.wrapRichTextStyle(name, style as Dictionary<unknown>);
450	}
451	
452	function wrapInlineValueRichText(
453	    ctx: TooltipMarkupBuildContext,
454	    values: string | string[],
455	    alignRight: boolean,
456	    valueCloseToMarker: boolean,
457	    style: RichTextStyle
458	): string {
459	    const styles: Dictionary<unknown>[] = [style];
460	    const paddingLeft = valueCloseToMarker ? 10 : 20;
461	    alignRight && styles.push({ padding: [0, 0, 0, paddingLeft], align: 'right' });
462	    // Value has commas inside, so use '  ' as delimiter for multiple values.
463	    return ctx.markupStyleCreator.wrapRichTextStyle(
464	        isArray(values) ? values.join('  ') : values,
465	        styles
466	    );
467	}
468	
469	
470	export function retrieveVisualColorForTooltipMarker(
471	    series: SeriesModel,
472	    dataIndex: number
473	): ColorString {
474	    const style = series.getData().getItemVisual(dataIndex, 'style');
475	    const color = style[series.visualDrawType];
476	    return convertToColorString(color);
477	}
478	
479	export function getPaddingFromTooltipModel(
480	    model: Model<TooltipOption>,
481	    renderMode: TooltipRenderMode
482	): number | number[] {
483	    const padding = model.get('padding');
484	    return padding != null
485	        ? padding
486	        // We give slightly different to look pretty.
487	        : renderMode === 'richText'
488	        ? [8, 10]
489	        : 10;
490	}
491	
492	/**
493	 * The major feature is generate styles for `renderMode: 'richText'`.
494	 * But it also serves `renderMode: 'html'` to provide
495	 * "renderMode-independent" API.
496	 */
497	export class TooltipMarkupStyleCreator {
498	    readonly richTextStyles: Dictionary<Dictionary<unknown>> = {};
499	
500	    // Notice that "generate a style name" usually happens repeatedly when mouse is moving and
501	    // a tooltip is displayed. So we put the `_nextStyleNameId` as a member of each creator
502	    // rather than static shared by all creators (which will cause it increase to fast).
503	    private _nextStyleNameId: number = getRandomIdBase();
504	
505	    private _generateStyleName() {
506	        return '__EC_aUTo_' + this._nextStyleNameId++;
507	    }
508	
509	    makeTooltipMarker(
510	        markerType: TooltipMarkerType,
511	        colorStr: ColorString,
512	        renderMode: TooltipRenderMode
513	    ): string {
514	        const markerId = renderMode === 'richText'
515	            ? this._generateStyleName()
516	            : null;
517	        const marker = getTooltipMarker({
518	            color: colorStr,
519	            type: markerType,
520	            renderMode,
521	            markerId: markerId
522	        });
523	        if (isString(marker)) {
524	            return marker;
525	        }
526	        else {
527	            if (__DEV__) {
528	                assert(markerId);
529	            }
530	            this.richTextStyles[markerId] = marker.style;
531	            return marker.content;
532	        }
533	    }
534	
535	    /**
536	     * @usage
537	     * ```ts
538	     * const styledText = markupStyleCreator.wrapRichTextStyle([
539	     *     // The styles will be auto merged.
540	     *     {
541	     *         fontSize: 12,
542	     *         color: 'blue'
543	     *     },
544	     *     {
545	     *         padding: 20
546	     *     }
547	     * ]);
548	     * ```
549	     */
550	    wrapRichTextStyle(text: string, styles: Dictionary<unknown> | Dictionary<unknown>[]): string {
551	        const finalStl = {};
552	        if (isArray(styles)) {
553	            each(styles, stl => extend(finalStl, stl));
554	        }
555	        else {
556	            extend(finalStl, styles);
557	        }
558	        const styleName = this._generateStyleName();
559	        this.richTextStyles[styleName] = finalStl;
560	        return `{${styleName}|${text}}`;
561	    }
562	}

