/*
* Safeguarding test for: fix(tooltip): fix tooltip XSS issue when legend name
* is HTML string (upstream apache/echarts#20045).
*
* A legend name containing HTML markup must be displayed as plain text in the
* legend item tooltip (renderMode 'html'), not injected as live markup.
*/

import { createChart, removeChart } from '../test/ut/core/utHelper';

describe('tooltip legend name XSS', function () {

    const legendName = '<img src="invalid-src" onerror="window.__tooltip_xss = 1">';

    function createLegendChart() {
        const chart = createChart();
        chart.setOption({
            xAxis: { type: 'category', data: ['Mon', 'Tue'] },
            yAxis: {},
            legend: {
                data: [legendName],
                tooltip: {
                    show: true
                }
            },
            series: [{
                type: 'line',
                name: legendName,
                data: [1, 2]
            }]
        });
        return chart;
    }

    function getTooltipDom(chart: ReturnType<typeof createChart>): HTMLElement {
        const candidates = chart.getDom().querySelectorAll('div');
        for (let i = 0; i < candidates.length; i++) {
            const el = candidates[i] as HTMLElement;
            if (el.style.position === 'absolute' && el.innerHTML.indexOf('&lt;img') >= 0) {
                return el;
            }
        }
        return null;
    }

    it('shows HTML legend name as encoded plain text in legend tooltip', function () {
        const chart = createLegendChart();
        chart.dispatchAction({
            type: 'showTip',
            legendIndex: 0,
            name: legendName
        });

        const tooltipEl = getTooltipDom(chart);
        expect(tooltipEl).toBeTruthy();
        // The markup must not be parsed into a real <img> element.
        expect(tooltipEl.querySelector('img')).toBeNull();
        // The raw text is still shown (as encoded entities).
        expect(tooltipEl.textContent).toContain(legendName);
        // And no script/error handler fired.
        expect((window as unknown as {__tooltip_xss?: number}).__tooltip_xss).toBeUndefined();

        removeChart(chart);
    });

    it('still shows ordinary legend names as-is in legend tooltip', function () {
        const chart = createChart();
        chart.setOption({
            xAxis: { type: 'category', data: ['Mon', 'Tue'] },
            yAxis: {},
            legend: {
                data: ['normal name'],
                tooltip: {
                    show: true
                }
            },
            series: [{
                type: 'line',
                name: 'normal name',
                data: [1, 2]
            }]
        });
        chart.dispatchAction({
            type: 'showTip',
            legendIndex: 0,
            name: 'normal name'
        });

        const candidates = chart.getDom().querySelectorAll('div');
        let found = false;
        for (let i = 0; i < candidates.length; i++) {
            if ((candidates[i] as HTMLElement).textContent === 'normal name') {
                found = true;
                break;
            }
        }
        expect(found).toBe(true);

        removeChart(chart);
    });
});

